$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$mp=Join-Path $root 'port-changes.json';$m=Get-Content $mp -Raw|ConvertFrom-Json
$targets=@(
 [pscustomobject]@{rel='foundation/advancement/AllAdvancements.java';changes=@([pscustomobject]@{from='b.icon(AllItems.CARDBOARD)';to='b.icon(AllBlocks.PACKAGER)'});status='Native logistics advancement chain retained; Cardboard prerequisite uses the Packager icon because the pinned Fabric baseline has no standalone Cardboard item registration.'},
 [pscustomobject]@{rel='compat/computercraft/implementation/peripherals/StationPeripheral.java';changes=@([pscustomobject]@{from='new TrainEditPacket.TrainEditReturnPacket(train.id, name, train.icon.getId(), train.mapColorIndex)';to='new TrainEditPacket.TrainEditReturnPacket(train.id, name, train.icon.getId())'});status='Native station peripheral train rename retained through the pinned baseline train-edit packet constructor.'},
 [pscustomobject]@{rel='content/logistics/stockTicker/StockKeeperCategoryMenu.java';changes=@([pscustomobject]@{from="`t@Override`n`tprotected Slot createPlayerSlot";to="`tprotected Slot createPlayerSlot"});status='Native Stock Keeper inactive player slots retained without an obsolete baseline override annotation.'}
)
foreach($t in $targets){$p=Join-Path $root "source/fabric/src/main/java/com/simibubi/create/$($t.rel)";$x=[IO.File]::ReadAllText($p);foreach($c in $t.changes){if(-not$x.Contains($c.from)){throw "Final simple ABI anchor missing in $($t.rel): $($c.from)"};$x=$x.Replace($c.from,$c.to)};[IO.File]::WriteAllText($p,$x,[Text.UTF8Encoding]::new($false));$e=$m.files|Where-Object path -eq $t.rel;$e.changes=@($e.changes)+$t.changes;$e.status=$t.status};$m|ConvertTo-Json -Depth 20|Set-Content $mp -Encoding utf8;Write-Output 'Cleared final simple ABI mismatches.'
